<template><view class="page"><view class="title heading">待响应派单</view><view v-for="item in list" :key="String(item.id)" class="card"><view>{{ item.taskNo || item.orderNo || '派单邀请' }}</view><view class="muted info">{{ item.productName || item.gameName }}</view><view class="buttons"><button size="mini" @click="reject(Number(item.id))">拒绝</button><button size="mini" class="primary" @click="accept(Number(item.id))">接受</button></view></view><EmptyState v-if="!list.length" /></view></template>
<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{acceptDispatch,getPendingDispatches,rejectDispatch}from'@/api/player';import EmptyState from '@/components/EmptyState.vue';import type{RecordData}from'@/types/api';const list=ref<RecordData[]>([]);async function load(){list.value=await getPendingDispatches()}onShow(load);async function accept(id:number){await acceptDispatch(id);uni.showToast({title:'接单成功'});await load()}async function reject(id:number){await rejectDispatch(id,'暂时无法服务');uni.showToast({title:'已拒绝'});await load()}</script>
<style scoped>.heading{margin-bottom:30rpx}.info{margin:18rpx 0}.buttons{display:flex;justify-content:flex-end;gap:20rpx}.buttons button{margin:0}</style>
